-- ============================================================
-- PMR Industries — April 1-29 2026 historical migration
-- 9 employees, 261 attendance rows, 9 ADJUSTMENT salary rows.
-- Source: PagarBook export (PMR INDUSTRIES Attendance Audit Logs Apr 2026.xlsx)
-- Run order: Section 1 (verify) -> Section 2 (attendance) -> Section 3 (offset) -> Section 4 (verify)
-- Idempotent: re-running is safe (deterministic ids + ON CONFLICT).
-- ============================================================


-- =====================================================
-- SECTION 1 — Sanity check. Run alone first.
-- Expect 9 rows back. Confirm openingBalance values match what you typed.
-- =====================================================
SELECT id, name, "monthlySalary", "openingBalance"
FROM "Employee"
WHERE id IN (
  'cmojs2gun0000l5049pw7up69', -- Bablu Yalmay
  'cmojs35ls0001l504u0g3ft1h', -- Baly Catuly
  'cmojs4q5n0000l204tu7bt91b', -- Bhupesh Dhenge
  'cmojs5iiv0001l2043abi3wsi', -- Kaveri Office
  'cmojs66pf0002l204c2oxyfue', -- Krishna Shebe
  'cmojs746e0003l204au1btdoy', -- Nitesh Rotke
  'cmojs7qo20004l2049cxv38h5', -- Sahil Shebe
  'cmojs8dhx0005l204pch3a3aj', -- Tularam Zalky
  'cmojs909r0006l204qut279fe'  -- सोपान बारसागडे
)
ORDER BY name;


-- =====================================================
-- SECTION 2 — Attendance INSERTs (261 rows, transactional)
-- All rows: source = ADMIN_MANUAL, approved = true, approvedAt = createdAt = 2026-04-29 12:00.
-- date  = UTC midnight of the IST calendar day (matches dateOnlyIST() convention).
-- =====================================================
BEGIN;

-- Bablu Yalmay (cmojs2gun0000l5049pw7up69) — 25 P / 4 A
ON CONFLICT ("employeeId", date) DO NOTHING;

-- Baly Catuly (cmojs35ls0001l504u0g3ft1h) — 29 P / 0 A
ON CONFLICT ("employeeId", date) DO NOTHING;

-- Bhupesh Dhenge (cmojs4q5n0000l204tu7bt91b) — 9 P / 20 A  (Apr 19 NoData -> ABSENT)
ON CONFLICT ("employeeId", date) DO NOTHING;

-- Kaveri Office (cmojs5iiv0001l2043abi3wsi) — 27 P / 2 A  (Apr 13 NoData -> ABSENT)
ON CONFLICT ("employeeId", date) DO NOTHING;

-- Krishna Shebe (cmojs66pf0002l204c2oxyfue) — 29 P / 0 A
ON CONFLICT ("employeeId", date) DO NOTHING;

-- Nitesh Rotke (cmojs746e0003l204au1btdoy) — 29 P / 0 A
ON CONFLICT ("employeeId", date) DO NOTHING;

-- Sahil Shebe (cmojs7qo20004l2049cxv38h5) — 29 P / 0 A
ON CONFLICT ("employeeId", date) DO NOTHING;

-- Tularam Zalky (cmojs8dhx0005l204pch3a3aj) — 26 P / 3 A  (Apr 21, 22, 26 NoData -> ABSENT)
ON CONFLICT ("employeeId", date) DO NOTHING;

-- सोपान बारसागडे (cmojs909r0006l204qut279fe) — 26 P / 3 A
ON CONFLICT ("employeeId", date) DO NOTHING;

COMMIT;


-- =====================================================
-- SECTION 3 — ADJUSTMENT SalaryPayments (9 rows)
-- amountPaid offsets the April earnings the engine will compute from approved attendance,
-- so the running balance shown by the app stays equal to the openingBalance you typed.
-- expenseId is intentionally NULL (paper offset, not a cash outflow).
-- =====================================================
BEGIN;

   "daysInMonth", "daysAttended", "monthlySalary",
   "calculatedAmount", "amountPaid", "paidDate", account, notes, "createdAt")
VALUES
  ('mig_adj_bablu',   'cmojs2gun0000l5049pw7up69', 'ADJUSTMENT', '2026-04-01 00:00:00', '2026-04-29 00:00:00', 30, 25, 11000.00,  9166.67,  9166.67, '2026-04-29 00:00:00', 'CASH', 'Migration offset: opening balance already includes Apr 1-29 earnings. Do not edit.', '2026-04-29 00:00:00'),
  ('mig_adj_baly',    'cmojs35ls0001l504u0g3ft1h', 'ADJUSTMENT', '2026-04-01 00:00:00', '2026-04-29 00:00:00', 30, 29, 12000.00, 11600.00, 11600.00, '2026-04-29 00:00:00', 'CASH', 'Migration offset: opening balance already includes Apr 1-29 earnings. Do not edit.', '2026-04-29 00:00:00'),
  ('mig_adj_bhupesh', 'cmojs4q5n0000l204tu7bt91b', 'ADJUSTMENT', '2026-04-01 00:00:00', '2026-04-29 00:00:00', 30,  9, 10000.00,  3000.00,  3000.00, '2026-04-29 00:00:00', 'CASH', 'Migration offset: opening balance already includes Apr 1-29 earnings. Do not edit.', '2026-04-29 00:00:00'),
  ('mig_adj_kaveri',  'cmojs5iiv0001l2043abi3wsi', 'ADJUSTMENT', '2026-04-01 00:00:00', '2026-04-29 00:00:00', 30, 27,  5000.00,  4500.00,  4500.00, '2026-04-29 00:00:00', 'CASH', 'Migration offset: opening balance already includes Apr 1-29 earnings. Do not edit.', '2026-04-29 00:00:00'),
  ('mig_adj_krishna', 'cmojs66pf0002l204c2oxyfue', 'ADJUSTMENT', '2026-04-01 00:00:00', '2026-04-29 00:00:00', 30, 29, 12000.00, 11600.00, 11600.00, '2026-04-29 00:00:00', 'CASH', 'Migration offset: opening balance already includes Apr 1-29 earnings. Do not edit.', '2026-04-29 00:00:00'),
  ('mig_adj_nitesh',  'cmojs746e0003l204au1btdoy', 'ADJUSTMENT', '2026-04-01 00:00:00', '2026-04-29 00:00:00', 30, 29, 20000.00, 19333.33, 19333.33, '2026-04-29 00:00:00', 'CASH', 'Migration offset: opening balance already includes Apr 1-29 earnings. Do not edit.', '2026-04-29 00:00:00'),
  ('mig_adj_sahil',   'cmojs7qo20004l2049cxv38h5', 'ADJUSTMENT', '2026-04-01 00:00:00', '2026-04-29 00:00:00', 30, 29, 10000.00,  9666.67,  9666.67, '2026-04-29 00:00:00', 'CASH', 'Migration offset: opening balance already includes Apr 1-29 earnings. Do not edit.', '2026-04-29 00:00:00'),
  ('mig_adj_tularam', 'cmojs8dhx0005l204pch3a3aj', 'ADJUSTMENT', '2026-04-01 00:00:00', '2026-04-29 00:00:00', 30, 26, 10000.00,  8666.67,  8666.67, '2026-04-29 00:00:00', 'CASH', 'Migration offset: opening balance already includes Apr 1-29 earnings. Do not edit.', '2026-04-29 00:00:00'),
  ('mig_adj_sopan',   'cmojs909r0006l204qut279fe', 'ADJUSTMENT', '2026-04-01 00:00:00', '2026-04-29 00:00:00', 30, 26, 11000.00,  9533.33,  9533.33, '2026-04-29 00:00:00', 'CASH', 'Migration offset: opening balance already includes Apr 1-29 earnings. Do not edit.', '2026-04-29 00:00:00')
ON CONFLICT ("id") DO NOTHING;

COMMIT;


-- =====================================================
-- SECTION 4 — Verification queries.
-- Run after Sections 2 + 3 commit. All numbers should match the plan.
-- =====================================================

-- 4A. Per-employee P/A counts for Apr 1-29.
-- Expect: Bablu 25/4, Baly 29/0, Bhupesh 9/20, Kaveri 27/2, Krishna 29/0,
--         Nitesh 29/0, Sahil 29/0, Tularam 26/3, सोपान 26/3.
SELECT e.name,
       SUM(CASE WHEN a.status = 'PRESENT' THEN 1 ELSE 0 END) AS present,
       SUM(CASE WHEN a.status = 'ABSENT'  THEN 1 ELSE 0 END) AS absent,
       COUNT(*) AS total
FROM "AttendanceRecord" a
JOIN "Employee" e ON e.id = a."employeeId"
WHERE a.date >= '2026-04-01' AND a.date <= '2026-04-29'
  AND e.id IN (
    'cmojs2gun0000l5049pw7up69','cmojs35ls0001l504u0g3ft1h','cmojs4q5n0000l204tu7bt91b',
    'cmojs5iiv0001l2043abi3wsi','cmojs66pf0002l204c2oxyfue','cmojs746e0003l204au1btdoy',
    'cmojs7qo20004l2049cxv38h5','cmojs8dhx0005l204pch3a3aj','cmojs909r0006l204qut279fe'
  )
GROUP BY e.name
ORDER BY e.name;

-- 4B. Computed running balance per employee.
-- Should equal "openingBalance" within ±0.01 (rounding tolerance).
SELECT e.name,
       e."openingBalance",
       e."openingBalance"
         + ROUND(e."monthlySalary"
                 * SUM(CASE WHEN a.status = 'PRESENT' AND a.approved THEN 1 ELSE 0 END)::numeric
                 / 30, 2)
         - COALESCE((SELECT SUM("amountPaid") FROM "SalaryPayment" sp WHERE sp."employeeId" = e.id), 0)
       AS computed_current_balance,
       e."openingBalance"
         + ROUND(e."monthlySalary"
                 * SUM(CASE WHEN a.status = 'PRESENT' AND a.approved THEN 1 ELSE 0 END)::numeric
                 / 30, 2)
         - COALESCE((SELECT SUM("amountPaid") FROM "SalaryPayment" sp WHERE sp."employeeId" = e.id), 0)
         - e."openingBalance"
       AS drift
FROM "Employee" e
LEFT JOIN "AttendanceRecord" a ON a."employeeId" = e.id
WHERE e.id IN (
  'cmojs2gun0000l5049pw7up69','cmojs35ls0001l504u0g3ft1h','cmojs4q5n0000l204tu7bt91b',
  'cmojs5iiv0001l2043abi3wsi','cmojs66pf0002l204c2oxyfue','cmojs746e0003l204au1btdoy',
  'cmojs7qo20004l2049cxv38h5','cmojs8dhx0005l204pch3a3aj','cmojs909r0006l204qut279fe'
)
GROUP BY e.id, e.name, e."openingBalance", e."monthlySalary"
ORDER BY e.name;
